"""Generate the data catalogue pages ``docs/{lang}/catalog.md`` from a built database."""

from __future__ import annotations

from pathlib import Path

import duckdb

from .config import REPO_ROOT, Paths

TEXT = {
    "en": {
        "title": "Data catalogue",
        "intro": ("Generated by `armstat-db docs` from the database. {n_tables} tables in "
                  "{n_topics} topics, {n_obs} observations. Database built {built_at}."),
        "cols": ["Table", "Title", "Unit", "Period", "Cells"],
        "legend": "† – English text partly or fully machine-translated from Armenian.",
    },
    "hy": {
        "title": "Տվյալների կատալոգ",
        "intro": ("Ստեղծվել է `armstat-db docs` հրամանով տվյալների բազայից։ {n_tables} աղյուսակ "
                  "{n_topics} թեմայում, {n_obs} դիտարկում։ Բազան կառուցվել է {built_at}։"),
        "cols": ["Աղյուսակ", "Անվանում", "Չափման միավոր", "Ժամանակաշրջան", "Բջիջներ"],
        "legend": "† – անգլերեն տեքստը մասամբ կամ ամբողջությամբ մեքենայական թարգմանություն է։",
    },
    "ru": {
        "title": "Каталог данных",
        "intro": ("Сформирован командой `armstat-db docs` из базы данных. {n_tables} таблиц в "
                  "{n_topics} разделах, {n_obs} наблюдений. База собрана {built_at}."),
        "cols": ["Таблица", "Название", "Единица", "Период", "Ячейки"],
        "legend": ("Все русские тексты — машинный перевод. † – английский текст частично "
                   "или полностью переведён с армянского машинным способом."),
    },
}


def _num(n: int, lang: str) -> str:
    return f"{n:,}" if lang == "en" else f"{n:,}".replace(",", "\u00a0")


def _md(text: str | None) -> str:
    return (text or "").replace("|", "\\|").replace("\n", " ").strip()


def generate_docs(paths: Paths, docs_dir: Path | None = None) -> list[Path]:
    docs_dir = docs_dir or REPO_ROOT / "docs"
    con = duckdb.connect(str(paths.database), read_only=True)
    written = []
    try:
        info = dict(con.execute("SELECT key, value FROM build_info").fetchall())
        n_obs = con.execute("SELECT count(*) FROM observations").fetchone()[0]
        n_topics = con.execute("SELECT count(*) FROM topics").fetchone()[0]
        for lang, t in TEXT.items():
            topics = con.execute(f"""
                SELECT topic_id, level, code, coalesce(path_{lang}, path_en)
                FROM topic_paths ORDER BY topic_id""").fetchall()
            rows = con.execute(f"""
                SELECT dt.topic_id, d.table_id, coalesce(d.title_{lang}, d.title_en),
                       coalesce(d.unit_{lang}, d.unit_en), d.first_period, d.last_period,
                       d.n_cells, d.en_origin, d.url_{lang if lang != 'ru' else 'en'}
                FROM datasets d JOIN dataset_topics dt USING (table_id)
                ORDER BY dt.topic_id, d.table_id""").fetchall()
            by_topic: dict[str, list] = {}
            for r in rows:
                by_topic.setdefault(r[0], []).append(r[1:])
            n_tables = con.execute("SELECT count(*) FROM datasets").fetchone()[0]
            # topics shown: those with tables anywhere below them
            with_tables = set()
            for tid in by_topic:
                parts = tid.split("/")
                with_tables.update("/".join(parts[:i]) for i in range(1, len(parts) + 1))
            out = [f"# {t['title']}", "",
                   t["intro"].format(n_tables=n_tables, n_topics=n_topics,
                                     n_obs=_num(n_obs, lang),
                                     built_at=info.get("built_at", "?")),
                   "", t["legend"], ""]
            for topic_id, level, code, path in topics:
                tables = by_topic.get(topic_id)
                if topic_id not in with_tables:
                    continue
                out.append(f"{'#' * min(level + 1, 6)} {code + ' ' if code else ''}"
                           f"{_md(path.rsplit(' / ', 1)[-1])}")
                out.append("")
                if tables:
                    out.append("| " + " | ".join(t["cols"]) + " |")
                    out.append("|" + "---|" * len(t["cols"]))
                    for tid, title, unit, p0, p1, cells, origin, url in tables:
                        mark = " †" if origin != "armstat" else ""
                        period = f"{p0}–{p1}" if p0 and p1 and p0 != p1 else (p0 or "")
                        out.append(f"| [`{tid}`]({url}) | {_md(title)}{mark} | {_md(unit)} | "
                                   f"{period} | {_num(cells, lang)} |")
                    out.append("")
            path = docs_dir / lang / "catalog.md"
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text("\n".join(out) + "\n", encoding="utf-8")
            written.append(path)
    finally:
        con.close()
    return written
